css:
.mte-breath-glow{
  --mte-bg-ink:#e6f3ee;
  --mte-bg-dim:#7d9a92;
  --mte-bg-acc:#34d399;
  position:relative;
  box-sizing:border-box;
  width:100%;
  min-height:152px;
  padding:16px 16px 14px;
  border-radius:16px;
  overflow:hidden;
  isolation:isolate;
  color:var(--mte-bg-ink);
  background:radial-gradient(130% 150% at 14% 0%,#122120 0%,#0a0f13 58%,#080b0f 100%);
  border:1px solid rgba(52,211,153,.16);
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mte-breath-glow *{
  box-sizing:border-box;
}
.mte-breath-glow .mte-breath-glow-aura{
  position:absolute;
  left:50%;
  top:58%;
  width:300px;
  height:300px;
  margin:-150px 0 0 -150px;
  border-radius:50%;
  pointer-events:none;
  z-index:0;
  background:radial-gradient(circle at 50% 50%,rgba(52,211,153,.42) 0%,rgba(45,212,191,.2) 40%,rgba(16,185,129,0) 70%);
  filter:blur(4px);
  animation:mte-breath-glow-breathe 7.6s ease-in-out infinite;
}
.mte-breath-glow .mte-breath-glow-aura::after{
  content:"";
  position:absolute;
  inset:26%;
  border-radius:50%;
  background:radial-gradient(circle at 50% 50%,rgba(125,211,252,.22),rgba(125,211,252,0) 70%);
  animation:mte-breath-glow-counter 11.4s ease-in-out infinite;
}
.mte-breath-glow .mte-breath-glow-body{
  position:relative;
  z-index:1;
  display:flex;
  flex-direction:column;
  gap:10px;
}
.mte-breath-glow .mte-breath-glow-head{
  display:flex;
  align-items:center;
  gap:8px;
}
.mte-breath-glow .mte-breath-glow-dot{
  position:relative;
  width:8px;
  height:8px;
  flex:0 0 auto;
  border-radius:50%;
  background:var(--mte-bg-acc);
  box-shadow:0 0 10px rgba(52,211,153,.75);
}
.mte-breath-glow .mte-breath-glow-dot::after{
  content:"";
  position:absolute;
  inset:-4px;
  border-radius:50%;
  border:1px solid rgba(52,211,153,.55);
  animation:mte-breath-glow-ping 3.8s ease-out infinite;
}
.mte-breath-glow .mte-breath-glow-title{
  font-size:14px;
  font-weight:600;
  letter-spacing:-.01em;
}
.mte-breath-glow .mte-breath-glow-state{
  margin-left:auto;
  padding:3px 8px;
  border-radius:99px;
  font-size:10px;
  font-weight:600;
  letter-spacing:.09em;
  text-transform:uppercase;
  color:#062b20;
  background:linear-gradient(180deg,#4ade80,#22c9a0);
}
.mte-breath-glow .mte-breath-glow-copy{
  margin:0;
  font-size:12.5px;
  line-height:1.5;
  color:var(--mte-bg-dim);
  max-width:34ch;
}
.mte-breath-glow .mte-breath-glow-foot{
  display:flex;
  align-items:center;
  gap:10px;
  margin-top:2px;
}
.mte-breath-glow .mte-breath-glow-metric{
  font-family:ui-monospace,Menlo,monospace;
  font-size:13px;
  color:#dff5ec;
}
.mte-breath-glow .mte-breath-glow-metric i{
  font-style:normal;
  font-size:10px;
  color:var(--mte-bg-dim);
  margin-left:1px;
}
.mte-breath-glow .mte-breath-glow-sep{
  width:1px;
  height:12px;
  background:rgba(255,255,255,.14);
}
.mte-breath-glow .mte-breath-glow-btn{
  margin-left:auto;
  padding:6px 11px;
  border-radius:9px;
  font:inherit;
  font-size:11.5px;
  color:#cfe9e0;
  background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.11);
  cursor:pointer;
  transition:background .2s ease,border-color .2s ease,color .2s ease,transform .12s ease;
}
.mte-breath-glow .mte-breath-glow-btn:hover{
  background:rgba(52,211,153,.14);
  border-color:rgba(52,211,153,.4);
  color:#eafff7;
}
.mte-breath-glow .mte-breath-glow-btn:focus-visible{
  outline:2px solid #6ee7b7;
  outline-offset:2px;
}
.mte-breath-glow .mte-breath-glow-btn:active{
  transform:translateY(1px);
}
.mte-breath-glow.mte-breath-glow--still .mte-breath-glow-aura,
.mte-breath-glow.mte-breath-glow--still .mte-breath-glow-aura::after,
.mte-breath-glow.mte-breath-glow--still .mte-breath-glow-dot::after{
  animation-play-state:paused;
}
@keyframes mte-breath-glow-breathe{
  0%,100%{transform:scale(.86);opacity:.5}
  50%{transform:scale(1.08);opacity:1}
}
@keyframes mte-breath-glow-counter{
  0%,100%{transform:scale(1.1);opacity:.35}
  50%{transform:scale(.8);opacity:.8}
}
@keyframes mte-breath-glow-ping{
  0%{transform:scale(.7);opacity:.9}
  70%,100%{transform:scale(2.1);opacity:0}
}
@media (prefers-reduced-motion: reduce){
  .mte-breath-glow .mte-breath-glow-aura,
  .mte-breath-glow .mte-breath-glow-aura::after,
  .mte-breath-glow .mte-breath-glow-dot::after{
    animation:none;
  }
  .mte-breath-glow .mte-breath-glow-aura{
    opacity:.6;
    transform:scale(1);
  }
}

js:
var btn = root.querySelector('.mte-breath-glow-btn');
if (btn) {
  btn.addEventListener('click', function () {
    var still = root.classList.toggle('mte-breath-glow--still');
    btn.setAttribute('aria-pressed', still ? 'true' : 'false');
    btn.textContent = still ? 'Resume ambience' : 'Pause ambience';
  });
}

css:
.mte-drift-mesh{
  position:relative;
  box-sizing:border-box;
  width:100%;
  min-height:164px;
  padding:18px 16px;
  border-radius:18px;
  overflow:hidden;
  isolation:isolate;
  color:#eceafd;
  background:#0b0a16;
  border:1px solid rgba(139,124,246,.18);
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mte-drift-mesh *{
  box-sizing:border-box;
}
.mte-drift-mesh .mte-drift-mesh-field{
  position:absolute;
  inset:-30%;
  z-index:0;
  filter:blur(30px) saturate(135%);
  pointer-events:none;
}
.mte-drift-mesh .mte-drift-mesh-blob{
  position:absolute;
  display:block;
  border-radius:50%;
  mix-blend-mode:screen;
}
.mte-drift-mesh .mte-drift-mesh-blob--a{
  width:56%;
  height:74%;
  left:4%;
  top:6%;
  background:radial-gradient(circle at 50% 50%,rgba(129,110,247,.85),rgba(129,110,247,0) 68%);
  animation:mte-drift-mesh-a 27s ease-in-out infinite;
}
.mte-drift-mesh .mte-drift-mesh-blob--b{
  width:52%;
  height:68%;
  right:2%;
  top:16%;
  background:radial-gradient(circle at 50% 50%,rgba(56,189,248,.7),rgba(56,189,248,0) 68%);
  animation:mte-drift-mesh-b 34s ease-in-out infinite;
}
.mte-drift-mesh .mte-drift-mesh-blob--c{
  width:48%;
  height:60%;
  left:26%;
  bottom:2%;
  background:radial-gradient(circle at 50% 50%,rgba(244,114,182,.55),rgba(244,114,182,0) 66%);
  animation:mte-drift-mesh-c 41s ease-in-out infinite;
}
.mte-drift-mesh .mte-drift-mesh-grid{
  position:absolute;
  inset:0;
  z-index:0;
  pointer-events:none;
  opacity:.5;
  background-image:linear-gradient(rgba(255,255,255,.05) 1px,rgba(0,0,0,0) 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,rgba(0,0,0,0) 1px);
  background-size:34px 34px;
  mask-image:radial-gradient(120% 90% at 50% 40%,#000 20%,rgba(0,0,0,0) 78%);
  -webkit-mask-image:radial-gradient(120% 90% at 50% 40%,#000 20%,rgba(0,0,0,0) 78%);
}
.mte-drift-mesh .mte-drift-mesh-body{
  position:relative;
  z-index:1;
  display:flex;
  flex-direction:column;
  gap:12px;
}
.mte-drift-mesh .mte-drift-mesh-eyebrow{
  font-size:10px;
  font-weight:600;
  letter-spacing:.16em;
  text-transform:uppercase;
  color:#b3a9f7;
}
.mte-drift-mesh .mte-drift-mesh-title{
  margin:0;
  font-size:19px;
  line-height:1.24;
  font-weight:650;
  letter-spacing:-.022em;
  max-width:16ch;
  text-wrap:balance;
}
.mte-drift-mesh .mte-drift-mesh-actions{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}
.mte-drift-mesh .mte-drift-mesh-cta{
  padding:8px 14px;
  border-radius:10px;
  font:inherit;
  font-size:12.5px;
  font-weight:600;
  color:#120c26;
  background:linear-gradient(180deg,#f4f2ff,#cdc4fb);
  border:1px solid rgba(255,255,255,.5);
  cursor:pointer;
  box-shadow:0 6px 18px rgba(93,66,214,.35);
  transition:transform .16s cubic-bezier(.2,.8,.3,1),box-shadow .2s ease,filter .2s ease;
}
.mte-drift-mesh .mte-drift-mesh-cta:hover{
  transform:translateY(-1px);
  box-shadow:0 10px 24px rgba(93,66,214,.5);
  filter:brightness(1.04);
}
.mte-drift-mesh .mte-drift-mesh-cta:active{
  transform:translateY(1px);
  box-shadow:0 3px 10px rgba(93,66,214,.4);
}
.mte-drift-mesh .mte-drift-mesh-ghost{
  padding:8px 12px;
  border-radius:10px;
  font:inherit;
  font-size:12.5px;
  color:#d8d3fb;
  background:rgba(255,255,255,.04);
  border:1px solid rgba(255,255,255,.14);
  cursor:pointer;
  transition:background .2s ease,border-color .2s ease,color .2s ease;
}
.mte-drift-mesh .mte-drift-mesh-ghost:hover{
  background:rgba(255,255,255,.1);
  border-color:rgba(255,255,255,.28);
  color:#fff;
}
.mte-drift-mesh .mte-drift-mesh-cta:focus-visible,
.mte-drift-mesh .mte-drift-mesh-ghost:focus-visible{
  outline:2px solid #a5b4fc;
  outline-offset:2px;
}
@keyframes mte-drift-mesh-a{
  0%,100%{transform:translate3d(0,0,0) scale(1)}
  33%{transform:translate3d(16%,10%,0) scale(1.14)}
  66%{transform:translate3d(-9%,16%,0) scale(.92)}
}
@keyframes mte-drift-mesh-b{
  0%,100%{transform:translate3d(0,0,0) scale(1.06)}
  40%{transform:translate3d(-18%,12%,0) scale(.9)}
  70%{transform:translate3d(-6%,-12%,0) scale(1.18)}
}
@keyframes mte-drift-mesh-c{
  0%,100%{transform:translate3d(0,0,0) scale(.96)}
  45%{transform:translate3d(14%,-16%,0) scale(1.2)}
  75%{transform:translate3d(-14%,-6%,0) scale(1)}
}
@media (prefers-reduced-motion: reduce){
  .mte-drift-mesh .mte-drift-mesh-blob--a,
  .mte-drift-mesh .mte-drift-mesh-blob--b,
  .mte-drift-mesh .mte-drift-mesh-blob--c{
    animation:none;
  }
  .mte-drift-mesh .mte-drift-mesh-cta{
    transition:none;
  }
}

.mte-grain-veil{
  position:relative;
  box-sizing:border-box;
  width:100%;
  min-height:158px;
  margin:0;
  padding:18px 17px 14px;
  border-radius:14px;
  overflow:hidden;
  isolation:isolate;
  color:#f2e7d8;
  background:linear-gradient(168deg,#1a1511 0%,#0d0b09 62%,#0a0908 100%);
  border:1px solid rgba(214,168,106,.2);
  font-family:ui-serif,Georgia,"Times New Roman",serif;
}
.mte-grain-veil *{
  box-sizing:border-box;
}
.mte-grain-veil .mte-grain-veil-noise{
  position:absolute;
  inset:-12px;
  z-index:0;
  pointer-events:none;
  opacity:.9;
  background-image:repeating-conic-gradient(from 12deg,rgba(255,238,214,.075) 0% 25%,rgba(0,0,0,0) 0% 50%),repeating-conic-gradient(from 47deg,rgba(120,90,60,.09) 0% 25%,rgba(0,0,0,0) 0% 50%);
  background-size:3px 3px,5px 5px;
  animation:mte-grain-veil-jitter 1.25s steps(1,end) infinite;
}
.mte-grain-veil.mte-grain-veil--coarse .mte-grain-veil-noise{
  background-size:6px 6px,11px 11px;
  opacity:1;
  animation-duration:2s;
}
.mte-grain-veil .mte-grain-veil-vignette{
  position:absolute;
  inset:0;
  z-index:0;
  pointer-events:none;
  background:radial-gradient(120% 100% at 30% 0%,rgba(233,178,110,.16),rgba(0,0,0,0) 55%),radial-gradient(140% 120% at 50% 120%,rgba(0,0,0,.55),rgba(0,0,0,0) 60%);
}
.mte-grain-veil .mte-grain-veil-quote{
  position:relative;
  z-index:1;
  margin:0 0 12px;
  font-size:17px;
  line-height:1.36;
  letter-spacing:-.012em;
  max-width:26ch;
}
.mte-grain-veil .mte-grain-veil-quote::before{
  content:"\201C";
  position:absolute;
  left:-10px;
  top:-6px;
  font-size:34px;
  line-height:1;
  color:rgba(233,178,110,.35);
}
.mte-grain-veil .mte-grain-veil-meta{
  position:relative;
  z-index:1;
  display:flex;
  flex-direction:column;
  gap:2px;
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mte-grain-veil .mte-grain-veil-who{
  font-size:12px;
  font-weight:600;
  color:#f6ecdd;
}
.mte-grain-veil .mte-grain-veil-role{
  font-size:11px;
  color:#a08f7b;
}
.mte-grain-veil .mte-grain-veil-controls{
  position:absolute;
  right:12px;
  bottom:12px;
  z-index:2;
  display:flex;
  gap:2px;
  padding:2px;
  border-radius:99px;
  background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.1);
  backdrop-filter:blur(4px);
}
.mte-grain-veil .mte-grain-veil-seg{
  padding:4px 10px;
  border:0;
  border-radius:99px;
  background:rgba(0,0,0,0);
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  font-size:10.5px;
  letter-spacing:.05em;
  text-transform:uppercase;
  color:#b3a08a;
  cursor:pointer;
  transition:background .2s ease,color .2s ease;
}
.mte-grain-veil .mte-grain-veil-seg:hover{
  color:#f4e6d3;
  background:rgba(255,255,255,.07);
}
.mte-grain-veil .mte-grain-veil-seg:focus-visible{
  outline:2px solid #e9b26e;
  outline-offset:2px;
}
.mte-grain-veil .mte-grain-veil-seg.mte-grain-veil-seg--on{
  color:#1a1108;
  background:linear-gradient(180deg,#f0cd9c,#dda85f);
}
@keyframes mte-grain-veil-jitter{
  0%{background-position:0 0,0 0}
  16%{background-position:-9px 6px,7px -8px}
  33%{background-position:8px -5px,-6px 9px}
  50%{background-position:-6px -9px,9px 5px}
  66%{background-position:7px 8px,-8px -6px}
  83%{background-position:-8px 3px,4px 7px}
  100%{background-position:0 0,0 0}
}
@media (prefers-reduced-motion: reduce){
  .mte-grain-veil .mte-grain-veil-noise{
    animation:none;
    opacity:.55;
  }
  .mte-grain-veil .mte-grain-veil-seg{
    transition:none;
  }
}

js:
var segs = root.querySelectorAll('.mte-grain-veil-seg');
Array.prototype.forEach.call(segs, function (seg) {
  seg.addEventListener('click', function () {
    Array.prototype.forEach.call(segs, function (other) {
      var on = other === seg;
      other.classList.toggle('mte-grain-veil-seg--on', on);
      other.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    root.classList.toggle('mte-grain-veil--coarse', seg.getAttribute('data-grain') === 'coarse');
  });
});

css:
.mte-idle-pulse{
  box-sizing:border-box;
  width:100%;
  min-height:158px;
  padding:13px 12px;
  border-radius:14px;
  color:#dbe6f2;
  background:linear-gradient(180deg,#0f151f,#0a0e15);
  border:1px solid rgba(255,255,255,.07);
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mte-idle-pulse *{
  box-sizing:border-box;
}
.mte-idle-pulse .mte-idle-pulse-head{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  padding:0 4px 9px;
}
.mte-idle-pulse .mte-idle-pulse-label{
  font-size:10.5px;
  font-weight:600;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:#6f8298;
}
.mte-idle-pulse .mte-idle-pulse-count{
  font-family:ui-monospace,Menlo,monospace;
  font-size:10.5px;
  color:#4d7fa8;
}
.mte-idle-pulse .mte-idle-pulse-list{
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  flex-direction:column;
  gap:2px;
}
.mte-idle-pulse .mte-idle-pulse-row{
  display:flex;
  align-items:center;
  gap:10px;
  width:100%;
  padding:7px 8px;
  border:0;
  border-radius:10px;
  background:rgba(0,0,0,0);
  font:inherit;
  color:inherit;
  text-align:left;
  cursor:pointer;
  transition:background .18s ease;
}
.mte-idle-pulse .mte-idle-pulse-row:hover{
  background:rgba(255,255,255,.05);
}
.mte-idle-pulse .mte-idle-pulse-row:focus-visible{
  outline:2px solid #58b6f0;
  outline-offset:-1px;
}
.mte-idle-pulse .mte-idle-pulse-row[aria-pressed="true"]{
  background:rgba(88,182,240,.12);
  box-shadow:inset 0 0 0 1px rgba(88,182,240,.28);
}
.mte-idle-pulse .mte-idle-pulse-avatar{
  position:relative;
  flex:0 0 auto;
  width:28px;
  height:28px;
  border-radius:50%;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:10.5px;
  font-weight:700;
  letter-spacing:.02em;
  color:#08121b;
}
.mte-idle-pulse .mte-idle-pulse-avatar::after{
  content:"";
  position:absolute;
  inset:-3px;
  border-radius:50%;
  border:1.5px solid rgba(120,200,255,.55);
  opacity:0;
  animation:mte-idle-pulse-halo 5.4s ease-out infinite;
}
.mte-idle-pulse .mte-idle-pulse-avatar--a{
  background:linear-gradient(140deg,#7dd3fc,#38bdf8);
}
.mte-idle-pulse .mte-idle-pulse-avatar--b{
  background:linear-gradient(140deg,#a7f3d0,#34d399);
}
.mte-idle-pulse .mte-idle-pulse-avatar--b::after{
  border-color:rgba(52,211,153,.5);
  animation-delay:1.8s;
}
.mte-idle-pulse .mte-idle-pulse-avatar--c{
  background:linear-gradient(140deg,#fbcfe8,#c084fc);
}
.mte-idle-pulse .mte-idle-pulse-avatar--c::after{
  border-color:rgba(192,132,252,.5);
  animation-delay:3.6s;
}
.mte-idle-pulse .mte-idle-pulse-text{
  display:flex;
  flex-direction:column;
  gap:2px;
  min-width:0;
  flex:1 1 auto;
}
.mte-idle-pulse .mte-idle-pulse-name{
  font-size:12.5px;
  font-weight:600;
  letter-spacing:-.005em;
  color:#eaf2fb;
}
.mte-idle-pulse .mte-idle-pulse-sub{
  font-size:11px;
  color:#728799;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  animation:mte-idle-pulse-fade 6.8s ease-in-out infinite;
}
.mte-idle-pulse .mte-idle-pulse-item:nth-child(2) .mte-idle-pulse-sub{
  animation-delay:2.2s;
}
.mte-idle-pulse .mte-idle-pulse-item:nth-child(3) .mte-idle-pulse-sub{
  animation-delay:4.4s;
}
.mte-idle-pulse .mte-idle-pulse-time{
  flex:0 0 auto;
  font-family:ui-monospace,Menlo,monospace;
  font-size:10px;
  color:#55697c;
}
@keyframes mte-idle-pulse-halo{
  0%{transform:scale(.9);opacity:0}
  14%{opacity:.85}
  46%{transform:scale(1.35);opacity:0}
