js:
var field = root.querySelector('.mte-float-motes-field');
var value = root.querySelector('.mte-float-motes-value');
var btn = root.querySelector('.mte-float-motes-btn');
var i, mote, size;
for (i = 0; i < 18; i++) {
  mote = document.createElement('span');
  mote.className = 'mte-float-motes-mote';
  size = 2 + (i % 4);
  mote.style.left = (2 + (i * 5.7) % 95).toFixed(2) + '%';
  mote.style.width = size + 'px';
  mote.style.height = size + 'px';
  mote.style.opacity = (0.2 + (i % 5) * 0.14).toFixed(2);
  mote.style.animationDuration = (13 + (i % 7) * 2.6).toFixed(1) + 's';
  mote.style.animationDelay = '-' + (i * 1.41).toFixed(2) + 's';
  if (field) field.appendChild(mote);
}
if (btn) {
  btn.addEventListener('click', function () {
    var dim = root.classList.toggle('mte-float-motes--dim');
    btn.setAttribute('aria-pressed', dim ? 'true' : 'false');
    btn.textContent = dim ? 'Raise field' : 'Dim field';
  });
}
var tick = 0;
var timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  tick += 1;
  var drift = Math.round(Math.sin(tick / 3) * 7 + Math.cos(tick / 6.5) * 4);
  if (value) value.textContent = (1284 + drift).toLocaleString('en-US');
}, 2800);

