var card = root.querySelector('.mte-holo-shimmer-card');
var btn = root.querySelector('.mte-holo-shimmer-btn');
if (card) {
  root.addEventListener('pointermove', function (e) {
    var r = card.getBoundingClientRect();
    if (!r.width || !r.height) return;
    var px = (e.clientX - r.left) / r.width - 0.5;
    var py = (e.clientY - r.top) / r.height - 0.5;
    card.style.setProperty('--mte-hs-ry', (px * 9).toFixed(2) + 'deg');
    card.style.setProperty('--mte-hs-rx', (-py * 7).toFixed(2) + 'deg');
  });
  root.addEventListener('pointerleave', function () {
    card.style.setProperty('--mte-hs-ry', '0deg');
    card.style.setProperty('--mte-hs-rx', '0deg');
  });
}
if (btn) {
  btn.addEventListener('click', function () {
    var added = btn.getAttribute('aria-pressed') !== 'true';
    btn.setAttribute('aria-pressed', added ? 'true' : 'false');
    btn.textContent = added ? 'In wallet' : 'Add to wallet';
  });
}

