var btns = root.querySelectorAll('.mte-slow-orbit-btn');
var value = root.querySelector('.mte-slow-orbit-value');
var sub = root.querySelector('.mte-slow-orbit-sub');
Array.prototype.forEach.call(btns, function (btn) {
  btn.addEventListener('click', function () {
    Array.prototype.forEach.call(btns, function (other) {
      var on = other === btn;
      other.classList.toggle('mte-slow-orbit-btn--on', on);
      other.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    root.style.setProperty('--mte-so-arc', btn.getAttribute('data-arc'));
    if (value) value.textContent = btn.getAttribute('data-val');
    if (sub) sub.textContent = btn.getAttribute('data-sub');
