js:
var lamp = root.querySelector('.mte-lantern-drift-lamp');
if (lamp) {
  var place = function (cx, cy) {
    var r = root.getBoundingClientRect();
    if (!r.width || !r.height) return;
    root.style.setProperty('--mte-lantern-drift-x', (((cx - r.left) / r.width) * 100).toFixed(2) + '%');
    root.style.setProperty('--mte-lantern-drift-y', (((cy - r.top) / r.height) * 100).toFixed(2) + '%');
    root.classList.add('mte-lantern-drift--held');
  };
  var release = function () {
    root.classList.remove('mte-lantern-drift--held');
    root.style.removeProperty('--mte-lantern-drift-x');
    root.style.removeProperty('--mte-lantern-drift-y');
  };
  root.addEventListener('pointermove', function (e) { place(e.clientX, e.clientY); });
  root.addEventListener('pointerleave', release);
  root.addEventListener('focusin', function (e) {
    var t = e.target;
    if (!t || !t.getBoundingClientRect) return;
    var b = t.getBoundingClientRect();
    place(b.left + b.width / 2, b.top + b.height / 2);
  });
  root.addEventListener('focusout', function (e) {
    if (!e.relatedTarget || !root.contains(e.relatedTarget)) release();
  });
}

