js:
var MASKED = 'sk_live_••••••••••••7f2a';
var FULL = 'sk_demo_EXAMPLEkey00NOTAREAL';
var code = root.querySelector('.mte-beam-border-code');
var reveal = root.querySelector('.mte-beam-border-reveal');
if (code && reveal) {
  reveal.addEventListener('click', function () {
    var shown = reveal.getAttribute('aria-pressed') !== 'true';
    reveal.setAttribute('aria-pressed', shown ? 'true' : 'false');
    reveal.textContent = shown ? 'Hide' : 'Reveal';
    code.textContent = shown ? FULL : MASKED;
  });
}
var rotate = root.querySelector('.mte-beam-border-rotate');
var note = root.querySelector('.mte-beam-border-note');
if (rotate && note) {
  var idle = note.textContent;
  rotate.addEventListener('click', function () {
    var staged = root.classList.toggle('mte-beam-border--staged');
    rotate.textContent = staged ? 'Cancel rotation' : 'Rotate key';
    note.textContent = staged ? 'Rotation staged. The new key is issued at 02:00 UTC and the old one stays valid for an hour.' : idle;
  });
}

