.mte-mist-plume .mte-mist-plume-head{
  position:relative;
  z-index:1;
  display:flex;
  align-items:center;
  gap:8px;
}
.mte-mist-plume .mte-mist-plume-room{
  font-size:13px;
  font-weight:600;
  letter-spacing:-.01em;
}
.mte-mist-plume .mte-mist-plume-state{
  padding:3px 8px;
  border-radius:99px;
  font-size:10px;
  letter-spacing:.05em;
  color:#a5e6ff;
  background:rgba(56,189,248,.12);
  border:1px solid rgba(56,189,248,.26);
}
.mte-mist-plume .mte-mist-plume-read{
  position:relative;
  z-index:1;
  display:flex;
  align-items:baseline;
  gap:9px;
  margin-top:11px;
}
.mte-mist-plume .mte-mist-plume-rh{
  font-size:29px;
  font-weight:600;
  letter-spacing:-.035em;
  color:#f4fbff;
}
.mte-mist-plume .mte-mist-plume-rh i{
  font-style:normal;
  font-size:14px;
  color:#7dd3fc;
  margin-left:2px;
}
.mte-mist-plume .mte-mist-plume-target{
  font-family:ui-monospace,Menlo,monospace;
  font-size:10.5px;
  color:#7c93a6;
}
.mte-mist-plume .mte-mist-plume-tank{
  position:relative;
  z-index:1;
  height:4px;
  margin:11px 0 12px;
  border-radius:3px;
  background:rgba(255,255,255,.08);
  overflow:hidden;
}
.mte-mist-plume .mte-mist-plume-tank-fill{
  display:block;
  width:72%;
  height:100%;
  border-radius:3px;
  background:linear-gradient(90deg,#38bdf8,#a5f3fc);
}
.mte-mist-plume .mte-mist-plume-modes{
  position:relative;
  z-index:1;
  display:inline-flex;
  padding:3px;
  gap:2px;
  border-radius:10px;
  background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.09);
}
.mte-mist-plume .mte-mist-plume-mode{
  padding:6px 12px;
  border-radius:7px;
  font:inherit;
  font-size:11.5px;
  color:#93a7ba;
  background:rgba(0,0,0,0);
  border:0;
  cursor:pointer;
  transition:color .18s ease,background .18s ease;
}
.mte-mist-plume .mte-mist-plume-mode:hover{
  color:#e8f6ff;
}
.mte-mist-plume .mte-mist-plume-mode:focus-visible{
  outline:2px solid #7dd3fc;
  outline-offset:2px;
}
.mte-mist-plume .mte-mist-plume-mode[aria-pressed="true"]{
  color:#04202e;
  font-weight:600;
  background:linear-gradient(180deg,#a5f3fc,#38bdf8);
}
@keyframes mte-mist-plume-rise{
  0%{transform:translate3d(0,0,0) scale(.45);opacity:0}
  14%{opacity:.8}
  56%{transform:translate3d(10px,-62px,0) scale(1.3);opacity:.46}
  100%{transform:translate3d(20px,-118px,0) scale(1.7);opacity:0}
}
@media (prefers-reduced-motion: reduce){
  .mte-mist-plume .mte-mist-plume-puff{
    animation:none;
    opacity:.34;
    transform:translate3d(8px,-40px,0) scale(1.2);
  }
}

js:
var modes = root.querySelectorAll('.mte-mist-plume-mode');
var state = root.querySelector('.mte-mist-plume-state');
var veils = { Low: '.55', Medium: '.85', High: '1' };
for (var i = 0; i < modes.length; i++) {
  modes[i].addEventListener('click', function (e) {
    var btn = e.currentTarget;
    for (var j = 0; j < modes.length; j++) {
      modes[j].setAttribute('aria-pressed', modes[j] === btn ? 'true' : 'false');
    }
    root.style.setProperty('--mte-mist-plume-rate', btn.getAttribute('data-rate'));
    root.style.setProperty('--mte-mist-plume-veil', veils[btn.textContent] || '.85');
    if (state) state.textContent = 'misting · ' + btn.textContent.toLowerCase();
  });
}
